package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
import org.jlinalg.cli.Monocle2DifferentialRequest.Request;
import org.jlinalg.cli.Monocle2DifferentialInputs.Population;

/** Typed original Monocle2 differentialGeneTest with explicit units and atomic batch admission. */
public final class Monocle2DifferentialCli {
    private Monocle2DifferentialCli() { }
    static final String SCOPE="Original Monocle2 2.26.0 differentialGeneTest on explicitly declared dense/sparse responses, typed metadata, VGAM families and nested additive/sm.ns model terms. Original size-factor/dispersion estimation and response transformations remain upstream. Complete original test/CDS objects, ordered axes and warnings are retained. Java independently audits finite probabilities and BH across original OK rows; it does not refit VGAM models. The original function does not return its internal fitted VGAM objects. Under this exact dependency profile, free-dispersion negbinomial and binary/proportion binomialff controls fail in the original helper with a multi-name family condition; no patch or result admission occurs. Exact versions/selected R bodies are checked; complete native-DLL/dependency source authentication, paper-version reconstruction and biological certification are not claimed. Logical capacities are not OS memory/disk quotas.";
    static final String ACTION="Read WARNINGS.md, analysis-status.json, worker/worker-report.json, worker/cases/ID/source-status.json and original stdout/stderr. Require result_admitted=true. SKIP3: run Linux Java with exact declared R4.2.1/Monocle2.26.0/private dependencies, including separate original HSMMSingleCell1.18.0, only where permitted; otherwise skip dependent analysis. Windows users can invoke Linux Java through WSL with Linux paths. Analysis installs nothing and never substitutes versions or Monocle3. FAIL2: no result of a failed atomic batch is admitted, including earlier completed cases. Preserve raw failed rows with p/q=1 and FAIL status; those are not valid null findings. Correct the named input/family/model/runtime/capacity cause and retry NEW paths without dropping genes, reordering IDs, imputation or value repair. No portable VERIFY interface is provided.";
    private record Captured(Path original,Path copy,NextflowFiles.Pin pin){void verify()throws IOException{require(pin.equals(NextflowFiles.pin(original,pin.bytes(),()->{}))&&pin.equals(NextflowFiles.pin(copy,pin.bytes(),()->{})),"Original or captured input changed: "+original);}}
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(output,"java -cp DEVELOPMENT.jar org.jlinalg.cli.Monocle2DifferentialCli --request ASCII_PATH.json\nRequire schema_version 1, mode DIFF, exact version, matrix_format dense-tsv/matrix-market, expression_units raw-integer-counts/continuous/binary/proportions, expression/cell_metadata/gene_metadata paths, metadata_types, rscript, r_home, r_libraries, analyses and NEW out.\nDense matrix header: gene_id then ordered literal cell IDs. Matrix Market uses general coordinate integer/real, with axes from ordered metadata; duplicate coordinates are refused. Metadata headers: cell_id plus declared covariates; gene_id<TAB>gene_short_name.\nEach analysis declares id, seed, family, lower_detection_limit, estimate_size_factors, dispersion, relative_expr, full_model and reduced_model. No arbitrary R, input RDS, implicit filters or missing values. Unknown options are refused.\n"+SCOPE+"\n"+ACTION);return 0;}
            require(args.length==2&&args[0].equals("--request"),"Require --request UTF8_JSON or --help");Path source=Path.of(args[1]).toAbsolutePath().normalize();var sourcePin=NextflowFiles.pin(source,1048576,()->{});byte[] raw=NextflowFiles.bytes(source,1048576);require(sourcePin.bytes()==raw.length&&sourcePin.sha256().equals(NextflowFiles.sha(raw)),"Request changed during intake");
            Request r=Monocle2DifferentialRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000)),source.getParent());
            var protectedPaths=new ArrayList<Path>(r.libraries());protectedPaths.add(r.rHome());Path resolvedOut=resolved(r.out());for(Path p:protectedPaths){Path protectedPath=resolved(p);require(!resolvedOut.startsWith(protectedPath)&&!protectedPath.startsWith(resolvedOut),"Output cannot overlap declared R libraries/home, including existing path aliases");}
            int[] exit={0};FollowupSupport.externalTransaction(Map.of("out",r.out().toString()),"original-monocle2-differential-development",(stage,manifest)->{
                var warnings=new ArrayList<String>();warnings.add(SCOPE);var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);
                try{
                    verify(source,sourcePin);Files.write(stage.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.effective());Path inputs=Files.createDirectory(stage.resolve("inputs"));var captured=new ArrayList<Captured>();long remaining=r.inputBytes();
                    for(var item:List.of(Map.entry(r.expression(),"expression"),Map.entry(r.cells(),"cell-metadata.tsv"),Map.entry(r.genes(),"gene-metadata.tsv"))){var c=capture(item.getKey(),inputs.resolve(item.getValue()),remaining);captured.add(c);remaining-=c.pin().bytes();}
                    Population p=Monocle2DifferentialInputs.validate(inputs,r);manifest.put("source_request_sha256",sourcePin.sha256());var inputPins=new LinkedHashMap<String,Object>();for(var c:captured)inputPins.put(c.copy().getFileName().toString(),Map.of("bytes",c.pin().bytes(),"sha256",c.pin().sha256()));manifest.put("captured_inputs",inputPins);
                    Path worker=Files.createDirectory(stage.resolve("worker"));NextflowFiles.writeJson(worker.resolve("parameters.json"),r.parameters());Monocle2DifferentialRuntime.sources(stage,"2.26.0",false);Monocle2DifferentialRuntime.run(stage,r,manifest);
                    diagnostics(read(worker.resolve("worker-report.json"),r.jsonBytes()),warnings);for(Captured c:captured)c.verify();verify(source,sourcePin);Monocle2DifferentialRuntime.sources(stage,"2.26.0",true);
                    var ledger=read(worker.resolve("input-ledger.json"),r.jsonBytes());require(strings(ledger.get("cell_ids"),1000000).equals(p.cells())&&strings(ledger.get("gene_ids"),1000000).equals(p.genes()),"Original input axis ledger differs");var reports=new ArrayList<Map<String,Object>>();
                    for(var a:r.analyses())reports.add(audit(worker.resolve("cases").resolve(text(a.get("id"))),a,p,r));
                    Path results=Files.createDirectory(stage.resolve("results"));for(var a:r.analyses())copyTree(worker.resolve("cases").resolve(text(a.get("id"))),results.resolve(text(a.get("id"))));
                    for(Captured c:captured)c.verify();verify(source,sourcePin);Monocle2DifferentialRuntime.sources(stage,"2.26.0",true);
                    NextflowFiles.writeJson(stage.resolve("report.json"),Map.of("version",r.version(),"genes",p.genes().size(),"cells",p.cells().size(),"input_stored_entries",p.storedEntries(),"input_explicit_zeros",p.explicitZeros(),"matrix_format",r.format(),"expression_units",r.units(),"analyses",reports,"scope",SCOPE,"analysis_installs_software",false));state.put("status","completed-with-warnings");state.put("result_admitted",true);state.put("analyses",reports.size());
                }catch(Monocle2DifferentialRuntime.Unavailable failure){exit[0]=3;state.put("status","SKIP3_DEPENDENT_ANALYSIS_SKIPPED");state.put("cause",failure.toString());warnings.add("SKIP3: "+failure);}
                catch(Exception failure){exit[0]=2;state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; no partial result admitted. Retry appropriate heap/capacities into NEW paths.");}
                if(exit[0]!=0){if(Files.exists(stage.resolve("results")))Files.move(stage.resolve("results"),stage.resolve("unadmitted-partial-results"));if(Files.exists(stage.resolve("report.json")))Files.move(stage.resolve("report.json"),stage.resolve("unadmitted-report.json"));Path wr=stage.resolve("worker/worker-report.json");if(Files.isRegularFile(wr))try{diagnostics(read(wr,r.jsonBytes()),warnings);}catch(IOException failure){warnings.add("Worker diagnostic read failed: "+failure);}}
                state.put("version",r.version());state.put("atomic_batch",true);state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("analysis_status",state.get("status"));manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope",SCOPE);
            });
            emit(exit[0]==0?output:error,(exit[0]==0?"Original Monocle2 differential analysis completed: ":exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+r.out());emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out().resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}catch(OutOfMemoryError failure){emit(error,"FAIL2 NO RESULT ADMITTED: Java heap exhausted. "+ACTION);return 2;}
    }
    private static Map<String,Object> audit(Path path,Map<String,Object> a,Population p,Request r)throws Exception {
        var status=read(path.resolve("source-status.json"),r.jsonBytes());require(text(status.get("status")).equals("original-returned"),"Original case did not return");var population=object(status.get("population"));require(integer(population.get("genes"),1,1000000)==p.genes().size()&&integer(population.get("cells"),2,1000000)==p.cells().size()&&Boolean.TRUE.equals(population.get("save_reload_identical")),"Original saved object axes/counts differ");
        var tests=table(path.resolve("tests.json"),r);require(tokens(tests,"source_row_name").equals(p.genes()),"Original test gene order differs");require(tokens(tests,"status").stream().allMatch("OK"::equals),"Original failed gene statuses; p/q=1 must not become valid nulls");
        double[] pv=probabilities(tokens(tests,"pval")),q=probabilities(tokens(tests,"qval"));require(pv.length==p.genes().size()&&q.length==pv.length,"Original test population differs");Integer[] order=new Integer[pv.length];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,Comparator.comparingDouble(i->pv[i]));double minimum=1,max=0;
        for(int rank=order.length-1;rank>=0;rank--){int index=order[rank];minimum=Math.min(minimum,(double)order.length/(rank+1)*pv[index]);double error=Math.abs(minimum-q[index]);require(error<=5e-13*Math.max(Math.abs(minimum),1e-300),"Original/native BH adjustment mismatch at gene "+p.genes().get(index));max=Math.max(max,error);}
        var cells=table(path.resolve("cells.json"),r);require(tokens(cells,"cell_id").equals(p.cells()),"Original cell-size-factor ledger order differs");
        var report=Map.<String,Object>of("id",a.get("id"),"original_test_rows",pv.length,"all_original_status_OK",true,"finite_probabilities",true,"native_BH_max_absolute_error",max,"models_refitted_in_Java",false,"save_reload_identical",true);
        NextflowFiles.writeJson(path.resolve("java-audit.json"),report);return report;
    }
    private static double[] probabilities(List<String> values)throws IOException {double[] p=new double[values.size()];for(int i=0;i<p.length;i++){try{p[i]=Double.parseDouble(values.get(i));}catch(NumberFormatException e){throw new IOException("Original probability is not finite numeric data",e);}require(Double.isFinite(p[i])&&p[i]>=0&&p[i]<=1,"Original probability is nonfinite/outside [0,1]; raw source values retained");}return p;}
    private static Map<String,Object> table(Path path,Request r)throws IOException {var m=read(path,r.jsonBytes());int rows=(int)integer(m.get("rows"),0,1000000);var names=new HashSet<String>();for(Object raw:list(m.get("columns"))){var c=object(raw);require(names.add(label(c.get("name"))),"Duplicate original output column");var values=literal(c.get("tokens"));var kinds=strings(c.get("kinds"),1000000);require(values.size()==rows&&kinds.size()==rows,"Ragged original output");for(int i=0;i<rows;i++){String k=kinds.get(i);require(Set.of("value","NA","NaN","positive-infinity","negative-infinity").contains(k),"Invalid original value kind");if(!k.equals("value"))require(values.get(i).equals(Map.of("NA","NA","NaN","NaN","positive-infinity","Inf","negative-infinity","-Inf").get(k)),"Original token/kind disagree");}}return m;}
    private static List<String> tokens(Map<String,Object> table,String column)throws IOException {for(Object raw:list(table.get("columns"))){var c=object(raw);if(text(c.get("name")).equals(column))return literal(c.get("tokens"));}throw new IOException("Missing original column: "+column);}
    private static List<String> literal(Object raw)throws IOException {var out=new ArrayList<String>();for(Object v:list(raw)){require(out.size()<1000000,"Original output population capacity exceeded");out.add(text(v));}return out;}
    static Map<String,Object> read(Path path,int bytes)throws IOException {return object(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(path,bytes)),bytes,20000000));}
    private static void diagnostics(Map<String,Object> report,List<String> warnings)throws IOException {for(Object w:list(report.get("warnings")))warnings.add("ORIGINAL R WARNING: "+text(w));if(!text(report.get("detail")).isEmpty())warnings.add("ORIGINAL R DETAIL: "+text(report.get("detail")));for(Object value:list(report.get("cases"))){var c=object(value);for(Object w:list(c.get("warnings")))warnings.add("ORIGINAL R WARNING ["+text(c.get("id"))+"]: "+text(w));if(c.get("original_error")!=null)warnings.add("ORIGINAL ERROR ["+text(c.get("id"))+"]: "+object(c.get("original_error")));}}
    private static Captured capture(Path original,Path copy,long capacity)throws IOException {require(capacity>=0,"Complete inputs exceed maximum_input_bytes");var pin=NextflowFiles.pin(original,capacity,()->{});long count=0;try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];for(int n=in.read(buffer);n>=0;n=in.read(buffer)){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Input capture cancelled");require(n<=capacity-count,"Input grew beyond capacity");out.write(buffer,0,n);count+=n;}}require(count==pin.bytes(),"Input changed during capture");var c=new Captured(original,copy,pin);c.verify();return c;}
    private static void verify(Path path,NextflowFiles.Pin p)throws IOException {require(p.equals(NextflowFiles.pin(path,p.bytes(),()->{})),"Original request changed");}
    private static Path resolved(Path path)throws IOException {var suffix=new ArrayList<Path>();Path parent=path;while(parent!=null&&!Files.exists(parent)){suffix.add(parent.getFileName());parent=parent.getParent();}require(parent!=null,"No existing ancestor for output/runtime path");Path result=parent.toRealPath();for(int i=suffix.size()-1;i>=0;i--)result=result.resolve(suffix.get(i));return result.normalize();}
    private static void copyTree(Path from,Path to)throws IOException {Files.createDirectory(to);try(var paths=Files.walk(from)){for(Path p:paths.toList()){if(p.equals(from))continue;require(!Files.isSymbolicLink(p),"Refuse result symlink");Path target=to.resolve(from.relativize(p));if(Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))Files.createDirectory(target);else{require(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS),"Refuse nonregular result");Files.copy(p,target);}}}}
    private static void emit(PrintStream output,String value){byte[] bytes=(value+"\n").getBytes(StandardCharsets.UTF_8);output.write(bytes,0,bytes.length);output.flush();}
}
